<script>
 let {operators=[], agents=[], requests=[], duplicates=0, lastSync='', onExport=()=>{}, onAgent=()=>{}}=$props();
 let minPool=$state(20), repeatLimit=$state(3), ageingHours=$state(24), staleHours=$state(2), now=$state(Date.now()), search=$state('');
 const number=(v)=>Number.isFinite(Number(v))?Number(v):0;
 const when=(raw)=>{if(!raw)return NaN;const s=String(raw).trim();const iso=s.includes('T')?s:s.replace(' ','T');return new Date(/(Z|[+-]\d\d:?\d\d)$/i.test(iso)?iso:iso+'Z').getTime()};
 let syncAge=$derived(Number.isFinite(when(lastSync))?(now-when(lastSync))/3600000:null);
 let poolAlerts=$derived(operators.filter(o=>number(o.assigned)>0&&number(o.available)<minPool).map(o=>({kind:'Pool capacity',severity:o.available===0?'Critical':'Attention',subject:o.operator,detail:`${o.available} available / ${o.assigned} assigned`,count:o.available,action:'Review operator pool'})));
 let repeatAgents=$derived(agents.filter(a=>number(a.requests)>=repeatLimit&&a.agent_number).sort((a,b)=>number(b.requests)-number(a.requests)).map(a=>({kind:'Repeat demand',severity:'Review',subject:a.agent_name||a.agent_number,detail:`${a.requests} requests · ${a.repeat_requests||0} repeat requests`,agent_number:a.agent_number,agent_name:a.agent_name,requests:number(a.requests)})));
 let aged=$derived(requests.filter(r=>['pending','approved','processing','review_required'].includes(String(r.status||'').toLowerCase())).map(r=>({...r,age:(now-when(r.first_call_utc||r.created_utc))/3600000})).filter(r=>Number.isFinite(r.age)&&r.age>=ageingHours).sort((a,b)=>b.age-a.age).map(r=>({kind:'Request ageing',severity:r.age>=ageingHours*2?'Critical':'Attention',subject:r.ticket_no||r.agent_name||r.agent_number||r.request_id||'Request',detail:`${Math.floor(r.age)}h pending · ${r.status}`,ticket_no:r.ticket_no||'',age_hours:Math.floor(r.age),agent_number:r.agent_number||''})));
 let alerts=$derived([
  ...(syncAge===null?[{kind:'Data freshness',severity:'Unknown',subject:'No confirmed DID inventory sync',detail:'Sync inventory before interpreting pool risk'}]:syncAge>staleHours?[{kind:'Data freshness',severity:'Attention',subject:'DID inventory is stale',detail:`Last sync ${Math.floor(syncAge)}h ago; verify cron health` }]:[]),
  ...(duplicates>0?[{kind:'Data integrity',severity:'Critical',subject:`${duplicates} duplicate inventory rows`,detail:'Investigate duplicate assignments before replacements'}]:[]),
  ...poolAlerts,...aged,...repeatAgents
 ]);
 let visible=$derived(alerts.filter(a=>`${a.kind} ${a.severity} ${a.subject} ${a.detail}`.toLowerCase().includes(search.trim().toLowerCase())));
 let critical=$derived(alerts.filter(a=>a.severity==='Critical').length);
 let attention=$derived(alerts.filter(a=>a.severity==='Attention').length);
 let unknown=$derived(alerts.filter(a=>a.severity==='Unknown').length);
 function exportAlerts(){onExport(visible.map(a=>({severity:a.severity,category:a.kind,subject:a.subject,detail:a.detail,agent_number:a.agent_number||'',ticket_no:a.ticket_no||'',generated_utc:new Date(now).toISOString()})),'did-risk-alerts.csv')}
</script>
<div class="risk-wrap">
 <div class="risk-header"><div><span class="risk-eyebrow">V84 · EARLY WARNING</span><h2>Operations Risk Radar</h2><p>Transparent operational signals from your existing synced data. No AI predictions or additional MCube calls.</p></div><div class="risk-actions"><button onclick={()=>now=Date.now()}>Recalculate</button><button class="risk-primary" onclick={exportAlerts} disabled={!visible.length}>Export alerts CSV</button></div></div>
 <div class="risk-summary"><div><small>Critical findings</small><strong class="red">{critical}</strong><span>Immediate investigation</span></div><div><small>Attention</small><strong class="orange">{attention}</strong><span>Threshold exceeded</span></div><div><small>Repeat-demand agents</small><strong>{repeatAgents.length}</strong><span>From recorded requests</span></div><div><small>Data freshness</small><strong>{syncAge===null?'Unknown':syncAge<1?`${Math.round(syncAge*60)}m`:`${Math.round(syncAge)}h`}</strong><span>Since last DID inventory sync</span></div></div>
 <div class="risk-layout"><section class="risk-panel risk-settings"><h3>Detection rules</h3><p>Adjust locally for analysis. No settings are saved or applied to DID replacement logic.</p><label>Low operator pool threshold <input type="number" min="0" max="10000" bind:value={minPool}/><small>Flag operators with fewer available DIDs</small></label><label>Agent request count <input type="number" min="2" max="10000" bind:value={repeatLimit}/><small>Flag agents with at least this many recorded requests</small></label><label>Pending request age <select bind:value={ageingHours}><option value={8}>8 hours</option><option value={24}>24 hours</option><option value={48}>48 hours</option><option value={72}>72 hours</option></select></label><label>Inventory freshness <select bind:value={staleHours}><option value={1}>1 hour</option><option value={2}>2 hours</option><option value={6}>6 hours</option><option value={12}>12 hours</option><option value={24}>24 hours</option></select></label><p class="risk-disclaimer">Pool threshold is a monitoring rule, not a depletion forecast. Repeat-demand counts may cover different time spans depending on available history.</p></section>
 <section class="risk-panel risk-results"><div class="risk-results-head"><div><h3>Priority findings</h3><p>{alerts.length} signals · {unknown} with unknown data state</p></div><input aria-label="Filter alerts" placeholder="Search alerts" bind:value={search}/></div><div class="risk-list">{#each visible.slice(0,150) as alert,i}<article class="risk-item"><span class:critical={alert.severity==='Critical'} class:attention={alert.severity==='Attention'} class="risk-dot"></span><div><div class="risk-tag">{alert.kind} · {alert.severity}</div><strong>{alert.subject}</strong><p>{alert.detail}</p>{#if alert.agent_number}<button class="risk-link" onclick={()=>onAgent(alert.agent_number,alert.agent_name||alert.subject)}>Open Agent 360° →</button>{/if}</div></article>{:else}<div class="risk-empty">No alerts match these rules. This does not guarantee the absence of operational issues.</div>{/each}</div>{#if visible.length>150}<p class="risk-foot">Showing 150 of {visible.length} signals. Export CSV for all filtered results.</p>{/if}</section></div>
 <div class="risk-method"><strong>How this works</strong><p>Alerts use current operator inventory, stored request status/timestamps, recorded agent request counts and the last inventory synchronization timestamp. They do not estimate future DID depletion, diagnose operator outages, or infer missing history. Refresh the underlying data before acting on alerts.</p></div>
</div>
<style>
 .risk-wrap{display:grid;gap:18px;color:#24334b}.risk-header{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.risk-eyebrow{font-size:10px;font-weight:800;letter-spacing:2px;color:#f97316}.risk-header h2{font-size:25px;letter-spacing:-.7px;margin:5px 0}.risk-header p,.risk-panel p{color:#64748b;font-size:13px;margin:5px 0}.risk-actions{display:flex;gap:8px}.risk-actions button,.risk-link{border:1px solid #dce4ed;background:#fff;border-radius:9px;padding:10px 13px;color:#344054;font-weight:650;cursor:pointer}.risk-actions .risk-primary{background:#f97316;border-color:#f97316;color:#fff}.risk-actions button:disabled{opacity:.45;cursor:not-allowed}.risk-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.risk-summary>div{padding:17px 18px;border:1px solid #e7ebf1;border-radius:14px;background:#fff;display:grid;gap:5px}.risk-summary small{font-size:12px;color:#64748b}.risk-summary strong{font-size:27px;font-weight:800}.risk-summary strong.red{color:#dc2626}.risk-summary strong.orange{color:#ea580c}.risk-summary span{font-size:11px;color:#94a3b8}.risk-layout{display:grid;grid-template-columns:minmax(220px,290px) minmax(0,1fr);gap:16px;align-items:start}.risk-panel{background:#fff;border:1px solid #e7ebf1;border-radius:16px;padding:19px}.risk-panel h3{font-size:16px;margin:0 0 5px}.risk-settings label{display:grid;gap:6px;font-size:12px;font-weight:650;margin-top:20px}.risk-settings input,.risk-settings select,.risk-results input{border:1px solid #dce4ed;border-radius:8px;padding:10px 11px;background:white;color:#24334b;max-width:100%;min-width:0}.risk-settings label small{font-size:11px;font-weight:400;color:#8a96a8}.risk-panel .risk-disclaimer{margin-top:24px;font-size:11px;background:#fff7ed;padding:12px;border-radius:9px}.risk-results-head{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;padding-bottom:14px;border-bottom:1px solid #eef2f6}.risk-results-head input{width:180px}.risk-list{display:grid;max-height:580px;overflow:auto}.risk-item{display:flex;align-items:flex-start;gap:13px;padding:14px 0;border-bottom:1px solid #f1f3f7}.risk-dot{height:10px;width:10px;flex:none;border-radius:50%;background:#94a3b8;margin-top:8px}.risk-dot.critical{background:#ef4444}.risk-dot.attention{background:#f97316}.risk-tag{font-size:10px;color:#94a3b8;text-transform:uppercase;letter-spacing:.7px;font-weight:750;margin-bottom:4px}.risk-item strong{font-size:13px;overflow-wrap:anywhere}.risk-item p{margin:4px 0!important;font-size:12px}.risk-link{border:0;color:#ea580c;padding:4px 0;font-size:12px}.risk-empty{padding:32px;text-align:center;color:#64748b;font-size:13px}.risk-foot{font-size:11px}.risk-method{border:1px solid #e7ebf1;background:#f8fafc;padding:16px;border-radius:12px}.risk-method strong{font-size:13px}.risk-method p{font-size:12px;line-height:1.6;color:#64748b;margin:6px 0 0}@media(max-width:900px){.risk-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.risk-layout{grid-template-columns:1fr}}@media(max-width:480px){.risk-summary{grid-template-columns:1fr 1fr}.risk-summary>div{padding:12px}.risk-header h2{font-size:21px}.risk-results-head input{width:100%}}
</style>
